import json
d=json.load(open('blog-synthesis.json'))
def walk(o,p='',depth=0):
    if depth>2: return
    if isinstance(o,dict):
        for k,v in o.items():
            print('  '*depth+f'{k}: {type(v).__name__}'+(f' len={len(v)}' if isinstance(v,(list,dict,str)) else ''))
            walk(v,p+'/'+k,depth+1)
    elif isinstance(o,list):
        if o: 
            print('  '*depth+f'[0] of {len(o)}: {type(o[0]).__name__}')
            walk(o[0],p+'[0]',depth+1)
walk(d)
